    static class Animal {}
    static class Cat extends Animal {}
    public static void main(String[] args) {
        Animal a = new Cat();
        System.out.println("a is Cat: " + (a instanceof Cat));
        Cat c = (Cat) a;
        System.out.println("downcast ok: " + (c != null));
        Animal d = new Animal();
